window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[116]={"id":"116","numero":116,"titre":"Prurit","objectifs":[{"id":"116-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition du prurit, du prurit sine materia et du prurit aquagénique","contenu":"<table >\n        <thead><tr><th>Terme</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Prurit</span></strong></td>\n            <td><span class=\"kw-def\">Signe fonctionnel, sensation qui provoque le besoin de se gratter</span>, localisé ou généralisé.<br>Concerne seulement <span class=\"kw-clinique\">la peau</span> et <span class=\"kw-clinique\">certaines (semi-)muqueuses</span> (<strong>pas toutes</strong> ⚠️).</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Prurit</span> physiologique</strong></td>\n            <td>Discret, plus important <span class=\"kw-clinique\">le soir</span> ou lorsqu’on se dévêt.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Prurit</span> pathologique</strong></td>\n            <td>Bascule pathologique dès qu’il induit :\n              <ul>\n                <li><strong>Lésions de grattage</strong></li>\n                <li><strong>Retentissement</strong> sur les activités quotidiennes ou le sommeil</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Prurit</span> sine materia</strong></td>\n            <td><span class=\"kw-def\">Prurit sans lésion cutanée spécifique</span> (en dehors des lésions secondaires de grattage). Oriente vers une cause générale (hématologique, hépatique, rénale, endocrinienne, médicamenteuse…).</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Prurit</span> aquagénique</strong></td>\n            <td><span class=\"kw-def\">Prurit déclenché par le contact de l’eau</span> (quelle que soit sa température), sans <span class=\"kw-clinique\">lésion</span> cutanée. À rechercher systématiquement <span class=\"kw-alerte\">une maladie de Vaquez</span> (polyglobulie primitive).</td>\n          </tr>\n        </tbody>\n      </table>","frequence":0},{"id":"116-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les mécanismes physiopathologiques du prurit","contenu":"<p><span class=\"kw-def\">Physiopathologie</span> <strong>complexe</strong>, non univoque.</p>\n      <ul>\n        <li><span class=\"kw-bio\">Histamine</span> : médiateur fréquemment impliqué, mais <strong>pas toujours</strong> (d’où l’efficacité partielle des anti-<span class=\"kw-chiffre\">H1</span>).</li>\n        <li>Le signal prurigineux peut naître :\n          <ul>\n            <li>Au niveau <span class=\"kw-clinique\">cutané</span> (terminaisons nerveuses libres dermo-épidermiques)</li>\n            <li>Plus haut dans les voies de transmission, au niveau du <span class=\"kw-clinique\">SNP</span> (fibres C amyéliniques) ou du <span class=\"kw-clinique\">SNC</span></li>\n          </ul>\n        </li>\n        <li>Autres médiateurs/voies impliqués selon les étiologies : sels biliaires, <span class=\"kw-ttt\">opioïdes</span> endogènes, cytokines, sérotonine, neuropeptides.</li>\n      </ul>\n      <div class=\"callout callout-info\">\n        <strong>Conséquence pratique.</strong> Les <span class=\"kw-ttt\">anti-histaminiques H1</span> ne sont efficaces que sur les prurits <strong>histamino-médiés</strong> (<span class=\"kw-clinique\">urticaire</span> ++). Sur les autres prurits, leur intérêt principal est <span class=\"kw-clinique\">sédatif</span> (anti-<span class=\"kw-chiffre\">H1</span> de 1ʳᵉ génération le soir).\n      </div>","frequence":0},{"id":"116-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’un prurit","contenu":"<p>Le <span class=\"kw-def\">diagnostic positif</span> est <strong>clinique</strong> : interrogatoire + examen cutanéo-muqueux complet.</p>\n\n      <h4>Lésions élémentaires à rechercher</h4>\n      <table >\n        <thead><tr><th>Type</th><th>Sémiologie</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Lésions de grattage</strong> (non spécifiques)</td>\n            <td><span class=\"kw-clinique\">Excoriations</span> ; <span class=\"kw-clinique\">stries linéaires</span> ; <span class=\"kw-clinique\">ulcérations</span>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Prurigo</span></strong> (chronicité)</td>\n            <td>Lésions <span class=\"kw-clinique\">papulo-vésiculeuses</span>, papules <span class=\"kw-clinique\">excoriées</span>, papules <span class=\"kw-clinique\">croûteuses</span>, <span class=\"kw-clinique\">nodules</span>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Lichénification</span></strong> (chronicité)</td>\n            <td>Peau <span class=\"kw-clinique\">épaissie</span>, <span class=\"kw-clinique\">grisâtre</span>, recouverte de fines <span class=\"kw-clinique\">squames</span> dessinant un <strong>quadrillage</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong>Surinfection</strong> 🦠</td>\n            <td><span class=\"kw-alerte\">Impétigo</span>, <span class=\"kw-alerte\">pyodermite</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span class=\"kw-def\">Diagnostic différentiel</span></h4>\n      <p>Autres sensations cutanées à distinguer : <span class=\"kw-clinique\">dysesthésies</span>, <span class=\"kw-clinique\">paresthésies</span>, <span class=\"kw-clinique\">douleur</span>.</p>\n\n      <h4>Démarche clinique d’orientation étiologique</h4>\n      <ul>\n        <li>Caractère <strong>localisé</strong> ou <strong>diffus</strong> du <span class=\"kw-clinique\">prurit</span></li>\n        <li>Évaluation de la <strong>sévérité</strong> : insomnie, troubles du comportement, <span class=\"kw-clinique\">AEG</span>…</li>\n        <li><strong>Circonstances</strong> déclenchantes, aggravantes, apaisantes ; <strong>horaires</strong> de survenue</li>\n        <li><strong>Métier</strong>, prise de <strong>médicament</strong>, caractère <strong>collectif</strong> (entourage)</li>\n        <li>Recherche d’<strong>autres lésions cutanées</strong>, d’un <strong>dermographisme</strong>, d’une <strong>organomégalie</strong></li>\n      </ul>","frequence":0},{"id":"116-4","rang":"B","rubrique":"Contenu multimédia","titre":"Photographie d’une lésion typique de prurigo","contenu":"<p><span class=\"kw-def\">Prurigo</span> = lésions <strong>secondaires</strong> à un <span class=\"kw-clinique\">prurit</span> chronique, traduisant les conséquences cutanées du grattage répété.</p>\n      <ul>\n        <li>Lésions <span class=\"kw-clinique\">papulo-vésiculeuses</span></li>\n        <li>Papules <span class=\"kw-clinique\">excoriées</span> par le grattage</li>\n        <li>Papules <span class=\"kw-clinique\">croûteuses</span></li>\n        <li><span class=\"kw-clinique\">Évolution</span> possible vers des <span class=\"kw-clinique\">nodules</span> de <span class=\"kw-clinique\">prurigo</span> (forme nodulaire chronique de Hyde)</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> Aucune image de <span class=\"kw-clinique\">lésion</span> typique de <span class=\"kw-clinique\">prurigo</span> n’a été déposée dans le dossier <code>fiches sources/116/</code>. Kevin déposera une photographie clinique dans <code>assets/images/116/</code> (ex. <code>prurigo-papulo-vesiculeux.jpg</code>) et le bloc <code>&lt;figure class=\"obj-figure\"&gt;</code> sera ajouté en B-FIX.\n      </div>\n      <!-- TODO Kevin : déposer photo prurigo dans assets/images/116/ + intégrer <figure> -->","frequence":0},{"id":"116-5","rang":"B","rubrique":"Contenu multimédia","titre":"Photographie d’une lésion typique de lichénification","contenu":"<p><span class=\"kw-def\">Lichénification</span> = épaississement cutané secondaire à un <span class=\"kw-clinique\">prurit</span> chronique avec frottements répétés.</p>\n      <ul>\n        <li>Peau <span class=\"kw-clinique\">épaissie</span>, <span class=\"kw-clinique\">grisâtre</span></li>\n        <li>Recouverte de fines <span class=\"kw-clinique\">squames</span></li>\n        <li>Dessinant un <span class=\"kw-clinique\">quadrillage</span> caractéristique (renforcement des plis cutanés)</li>\n        <li>Topographie élective : zones accessibles au grattage — nuque (névrodermite), avant-bras, jambes, OGE…</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> Aucune image de <span class=\"kw-clinique\">lichénification</span> n’a été déposée dans le dossier <code>fiches sources/116/</code>. Kevin déposera une photographie clinique dans <code>assets/images/116/</code> (ex. <code>lichenification-nuque.jpg</code>) et le bloc <code>&lt;figure class=\"obj-figure\"&gt;</code> sera ajouté en B-FIX.\n      </div>\n      <!-- TODO Kevin : déposer photo lichénification dans assets/images/116/ + intégrer <figure> -->","frequence":0},{"id":"116-6","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les examens à réaliser en première intention dans le cadre d’un prurit sine materia","contenu":"<p>Devant un <strong><span class=\"kw-clinique\">prurit</span> sine materia</strong>, un <strong>bilan paraclinique de 1ʳᵉ intention</strong> est systématique pour rechercher une cause générale.</p>\n\n      <table >\n        <thead><tr><th>Catégorie</th><th>Examens à demander</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Biologie</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-bio\">NFS-Plaquettes</span>, <span class=\"kw-bio\">Ferritine</span> → anémie ferriprive, hémopathie</li>\n                <li><span class=\"kw-bio\">γ-GT</span>, <span class=\"kw-bio\">PAL</span> → cholestase</li>\n                <li><span class=\"kw-bio\">Créatinine</span> → <span class=\"kw-ci\">insuffisance rénale</span></li>\n                <li><span class=\"kw-bio\">TSH</span> → dysthyroïdie</li>\n                <li><span class=\"kw-bio\">Électrophorèse des protéines plasmatiques</span> → LLC, gammapathie</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Microbiologie</strong></td>\n            <td><span class=\"kw-bio\">Sérologies</span> <span class=\"kw-bio\">VIH</span>, <span class=\"kw-bio\">VHB</span>, <span class=\"kw-bio\">VHC</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Imagerie</strong></td>\n            <td><span class=\"kw-imagerie\">RXT</span> (recherche d’un lymphome).</td>\n          </tr>\n          <tr>\n            <td><strong>Non indiqué</strong> ❌</td>\n            <td>\n              <ul>\n                <li><em><span class=\"kw-imagerie\"><span class=\"kw-imagerie\">Échographie</span> abdominale</span></em> (recherche cause hépatique) : citée dans l’ancien collège mais <strong>retirée</strong> du bilan de 1ʳᵉ intention</li>\n                <li><em><span class=\"kw-bio\">Biopsie</span> cutanée</em> : non indiquée en 1ʳᵉ intention</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 213 — Anémie · 264 — <span class=\"kw-def\">Insuffisance rénale chronique</span> · 167 — Hépatites virales · 169 — <span class=\"kw-etio\">VIH</span> · 318 — Leucémie lymphoïde chronique</em></p>","frequence":1},{"id":"116-7","rang":"A","rubrique":"Étiologies","titre":"Connaître l’arbre décisionnel pour le diagnostic étiologique du prurit","contenu":"<p>L’orientation étiologique repose sur deux axes successifs : <strong>localisé <span class=\"kw-bio\">vs</span> diffus</strong>, puis <strong>avec ou sans lésions cutanées spécifiques</strong>.</p>\n\n      <table class=\"matrix\">\n        <thead>\n          <tr>\n            <th></th>\n            <th>Avec lésions cutanées spécifiques</th>\n            <th>Sans <span class=\"kw-clinique\">lésion</span> (sine materia)</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Prurit</span> diffus</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Gale</span> (recrudescence nocturne, familial, sillons interdigitaux)</li>\n                <li><span class=\"kw-clinique\">Urticaire</span> / dermographisme</li>\n                <li><span class=\"kw-clinique\">Eczéma</span> (<span class=\"kw-etio\">atopique</span>, contact)</li>\n                <li>Toxidermies (<span class=\"kw-ttt\">médicaments</span>)</li>\n                <li><span class=\"kw-clinique\">Psoriasis</span>, mastocytose, lichen plan</li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li><span class=\"kw-bio\">Cholestase</span> (VBP, médicamenteuse, <span class=\"kw-ci\">grossesse</span>)</li>\n                <li><span class=\"kw-bio\">Insuffisance rénale</span> chronique</li>\n                <li><span class=\"kw-bio\">Hémopathies</span> : Vaquez, LLC, lymphome Hodgkin / LNH</li>\n                <li><span class=\"kw-bio\">Endocrinopathie</span> : dysthyroïdie</li>\n                <li><span class=\"kw-ttt\">Médicamenteux</span> (imputabilité)</li>\n                <li><span class=\"kw-bio\">VIH</span></li>\n                <li><span class=\"kw-clinique\">Prurit</span> <strong>sénile</strong> (<span class=\"kw-clinique\">xérose</span>) ; <span class=\"kw-clinique\">prurit</span> <strong>psychogène</strong> (élimination)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Prurit</span> localisé</strong></td>\n            <td>\n              <ul>\n                <li>Dermatoses débutantes (<span class=\"kw-clinique\">eczéma</span>, psoriasis, lichen…)</li>\n                <li><span class=\"kw-clinique\">Mycoses</span> (candidose, dermatophytose)</li>\n                <li><span class=\"kw-clinique\">Ectoparasitoses</span> (<span class=\"kw-etio\">gale</span>, pédiculose)</li>\n                <li><span class=\"kw-clinique\">Helminthiases tropicales</span> · larva migrans</li>\n                <li><span class=\"kw-clinique\">Dermatite</span> des nageurs (parasitoses autochtones)</li>\n                <li>Piqûres (insectes, végétaux)</li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Prurit</span> du <strong>cuir chevelu</strong> : pédiculose ++</li>\n                <li><span class=\"kw-clinique\">Prurit</span> <strong>anal</strong>, <strong>vulvaire</strong>, <strong>scrotal</strong> isolés</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Démarche systématique.</strong> Toujours rechercher : caractère <em>familial/collectif</em>, <em>horaire</em> nocturne, <em>circonstances</em> déclenchantes (eau, effort, contact), <em>médicaments</em> récents, <em>voyage tropical</em>, <em>organomégalie</em> à l’examen.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 171 — <span class=\"kw-etio\">Gale</span> et pédiculose · 187 — <span class=\"kw-ci\">Hypersensibilité</span>, allergies cutanées · 117 — <span class=\"kw-clinique\">Psoriasis</span> · 169 — <span class=\"kw-etio\">VIH</span></em></p>","frequence":1},{"id":"116-8","rang":"A","rubrique":"Étiologies","titre":"Connaître trois causes principales de prurit diffus avec lésions cutanées","contenu":"<p>Trois grandes causes à retenir devant un <strong><span class=\"kw-clinique\">prurit</span> diffus accompagné de lésions cutanées spécifiques</strong>.</p>\n\n      <table >\n        <thead><tr><th>Cause</th><th>Sémiologie</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Gale</span></strong> 🦠</td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Prurit</span> <span class=\"kw-clinique\">généralisé</span>, à <span class=\"kw-clinique\">recrudescence nocturne</span></li>\n                <li>Caractère <span class=\"kw-clinique\">familial / collectif</span> (entourage prurigineux)</li>\n                <li>Topographie évocatrice : espaces <strong>interdigitaux</strong>, face antérieure des <strong>poignets</strong>, <strong>OGE</strong>, <strong>mamelons</strong>, ombilic</li>\n                <li>Lésions spécifiques : sillons, vésicules perlées</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Urticaire</span></strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Papules œdémateuses</span> érythémateuses, prurigineuses, <strong>fugaces</strong> (&lt;<span class=\"kw-chiffre\"> 24 h</span> sur une zone)</li>\n                <li><span class=\"kw-clinique\">Dermographisme</span> possible</li>\n                <li>Mécanisme histaminique → bonne réponse aux <span class=\"kw-ttt\">anti-H1</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Eczéma</span></strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Lésions érythémato-vésiculeuses</span>, suintantes puis croûteuses, mal limitées</li>\n                <li><span class=\"kw-etio\">Atopique</span> (plis, enfant) ou de contact (topographie de contact)</li>\n                <li><span class=\"kw-clinique\">Évolution</span> vers <span class=\"kw-clinique\">lichénification</span> en cas de chronicité</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Autres dermatoses prurigineuses</strong> à connaître : <span class=\"kw-clinique\">psoriasis</span> (<span class=\"kw-clinique\">prurit</span> modéré), <span class=\"kw-clinique\">lichen plan</span> (papules violines striées), <span class=\"kw-clinique\">mastocytose</span> (<span class=\"kw-clinique\">urticaire</span> pigmentaire, signe de Darier), <span class=\"kw-clinique\">DBAI</span> (pemphigoïde bulleuse).\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 171 — <span class=\"kw-etio\">Gale</span> et pédiculose · 187 — <span class=\"kw-ci\">Hypersensibilité</span>, allergies cutanées · 117 — <span class=\"kw-clinique\">Psoriasis</span> · 112 — Dermatose bulleuse <span class=\"kw-etio\">auto-immune</span></em></p>","frequence":0},{"id":"116-9","rang":"A","rubrique":"Étiologies","titre":"Connaître les différentes causes de prurit diffus sine materia","contenu":"<p>Devant un <strong><span class=\"kw-clinique\">prurit</span> diffus sans <span class=\"kw-clinique\">lésion</span> cutanée spécifique</strong>, rechercher systématiquement une <strong>cause générale</strong>.</p>\n\n      <table >\n        <thead><tr><th>Catégorie</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Hépatique</strong></td>\n            <td><span class=\"kw-bio\">Cholestase</span> (VBP intra/extra-hépatique, <span class=\"kw-def\">cirrhose</span> biliaire primitive, médicamenteuse, gravidique).</td>\n          </tr>\n          <tr>\n            <td><strong>Rénale</strong></td>\n            <td><span class=\"kw-bio\">Insuffisance rénale chronique</span> évoluée, dialysée.</td>\n          </tr>\n          <tr>\n            <td><strong>Hématologique</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-bio\">Maladie de Vaquez</span> (polyglobulie primitive) — <strong><span class=\"kw-clinique\">prurit</span> aquagénique</strong> +++</li>\n                <li><span class=\"kw-bio\">Leucémie lymphoïde chronique (LLC)</span></li>\n                <li><span class=\"kw-bio\">Lymphome Hodgkin / LNH</span> — <span class=\"kw-clinique\">prurit</span> parfois inaugural</li>\n                <li>Anémie ferriprive</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Endocrinienne</strong></td>\n            <td><span class=\"kw-bio\">Dysthyroïdie</span> (<span class=\"kw-def\">hyperthyroïdie</span> ++).</td>\n          </tr>\n          <tr>\n            <td><strong>Infectieuse</strong></td>\n            <td><span class=\"kw-bio\">VIH</span> (<span class=\"kw-clinique\">prurit</span> fréquent, ± <span class=\"kw-clinique\">éruption</span> papuleuse).</td>\n          </tr>\n          <tr>\n            <td><strong>Médicamenteuse</strong></td>\n            <td><span class=\"kw-ttt\">Toxidermie</span> non éruptive — <span class=\"kw-ttt\">opiacés</span>, <span class=\"kw-ttt\">IEC</span>, β-bloquants, <span class=\"kw-ttt\">AINS</span>, ATB, antipaludéens… Imputabilité chronologique.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Prurit</span> sénile</strong></td>\n            <td>\n              <ul>\n                <li>Fréquent chez le sujet âgé, lié au <span class=\"kw-clinique\">vieillissement cutané</span> et des terminaisons nerveuses</li>\n                <li>Favorisé par la <span class=\"kw-clinique\">xérose cutanée</span></li>\n                <li>Intensité particulière, parfois <span class=\"kw-alerte\">insomniant</span> ; contraste avec discrétion des lésions</li>\n                <li>Retentissement psychique possible (<span class=\"kw-alerte\">dépression</span>) ⚠️</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Prurit</span> psychogène</strong></td>\n            <td><span class=\"kw-def\">Diagnostic d’élimination</span> (≠ <span class=\"kw-clinique\">prurit</span> idiopathique). Rechercher pathologie psychiatrique associée ou évènements stressants déclenchants.</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 167 — Hépatites virales · 264 — <span class=\"kw-def\">Insuffisance rénale chronique</span> · 318 — Leucémie lymphoïde chronique · 169 — <span class=\"kw-etio\">VIH</span> · 213 — Anémie</em></p>","frequence":0},{"id":"116-10","rang":"B","rubrique":"Étiologies","titre":"Connaître une cause de prurit aquagénique","contenu":"<div class=\"callout callout-info\">\n        <strong>Cause de référence à connaître :</strong> <span class=\"kw-alerte\">Maladie de Vaquez</span> (polyglobulie primitive — SMP <span class=\"kw-bio\">Ph</span> négatif, mutation JAK2 V617F).\n      </div>\n\n      <table >\n        <thead><tr><th>Item</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Définition</strong></td>\n            <td><span class=\"kw-def\">Prurit déclenché par le contact de l’eau</span>, quelle que soit sa température, sans <span class=\"kw-clinique\">lésion</span> cutanée.</td>\n          </tr>\n          <tr>\n            <td><strong>Cause à éliminer ++</strong></td>\n            <td><span class=\"kw-alerte\">Maladie de Vaquez</span> — à rechercher devant tout <span class=\"kw-clinique\">prurit</span> aquagénique inexpliqué.</td>\n          </tr>\n          <tr>\n            <td><strong>Examens d’orientation</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-bio\">NFS</span> : polyglobulie (Hb &gt;<span class=\"kw-chiffre\"> 16,5 g/dL</span> ♂ / &gt;<span class=\"kw-chiffre\"> 16,0 g/dL</span> ♀)</li>\n                <li><span class=\"kw-bio\">JAK2 V617F</span> mutation</li>\n                <li>Bilan martial, EPO sérique</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 318 — Leucémie lymphoïde chronique</em></p>","frequence":0},{"id":"116-11","rang":"A","rubrique":"Étiologies","titre":"Connaître une cause de prurit du scalp à rechercher systématiquement","contenu":"<div class=\"callout callout-info\">\n        <strong>Cause à rechercher systématiquement :</strong> <span class=\"kw-clinique\">Pédiculose du cuir chevelu</span> (<em><span class=\"kw-etio\">Pediculus</span> humanus capitis</em>) — quel que soit l’âge, le milieu social, à examen clinique soigneux des cheveux (lentes accrochées à la racine, derrière les oreilles, nuque).\n      </div>\n\n      <h4>Autres causes de <span class=\"kw-clinique\">prurit</span> du cuir chevelu</h4>\n      <ul>\n        <li><strong><span class=\"kw-ci\">Intolérance</span> / <span class=\"kw-clinique\">eczéma</span> de contact</strong> aux <span class=\"kw-ttt\">produits cosmétiques capillaires</span> (teintures, shampooings, défrisants)</li>\n        <li><strong>États pelliculaires simples</strong></li>\n        <li><strong><span class=\"kw-clinique\">Psoriasis</span></strong>, <strong><span class=\"kw-clinique\">dermatite</span> <span class=\"kw-clinique\">séborrhéique</span></strong></li>\n        <li><strong>Névrodermite</strong> de la nuque : <span class=\"kw-clinique\">lichénification</span> par grattage chronique</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 171 — <span class=\"kw-etio\">Gale</span> et pédiculose · 117 — <span class=\"kw-clinique\">Psoriasis</span> · 111 — Dermatose faciale</em></p>","frequence":0},{"id":"116-12","rang":"B","rubrique":"Étiologies","titre":"Connaître les causes de prurit localisé","contenu":"<p>Nombreuses dermatoses peuvent être responsables d’un <span class=\"kw-clinique\">prurit</span> localisé, <strong>surtout au début de leur <span class=\"kw-clinique\">évolution</span></strong>.</p>\n\n      <table >\n        <thead><tr><th>Catégorie</th><th>Étiologies & sémiologie</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Mycoses</strong></td>\n            <td><span class=\"kw-clinique\">Candidoses</span> ou <span class=\"kw-clinique\">dermatophytoses</span> (associées à des lésions spécifiques : <span class=\"kw-clinique\">placard</span> érythémato-squameux annulaire, bordure active).</td>\n          </tr>\n          <tr>\n            <td><strong>Ectoparasitoses</strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"kw-etio\">Gale</span> :</strong> <span class=\"kw-clinique\">prurit</span> généralisé, familial, recrudescence <span class=\"kw-clinique\">nocturne</span> ; espaces interdigitaux, poignets, OGE, mamelons</li>\n                <li><strong>Pédiculose :</strong> <span class=\"kw-clinique\">prurit</span> de la <span class=\"kw-clinique\">nuque</span> ou du <span class=\"kw-clinique\">cuir chevelu</span> ; évoquer chez l’enfant et les personnes en situation de précarité</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Helminthiases tropicales</strong></td>\n            <td>\n              <ul>\n                <li>Évoquées après <span class=\"kw-clinique\">séjour tropical</span> : onchocercose, loase, filariose lymphatique, bilharziose…</li>\n                <li>Rechercher une <span class=\"kw-bio\">hyperéosinophilie</span></li>\n                <li>Syndrome de <strong>larva migrans cutanée</strong> (ankylostomose, anguillulose) sur zones en contact avec le sol</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Parasitoses autochtones</strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"kw-clinique\">Dermatite</span> des nageurs :</strong> macules érythémateuses prurigineuses disséminées</li>\n                <li>Survient dans les heures suivant un bain en <span class=\"kw-clinique\">étang</span> (parasites d’oiseaux — puces des canards) ou en mer</li>\n                <li>Disparaissent en quelques jours</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Piqûres</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Insectes</span> (moustiques, puces, punaises, aoûtats…) ou <span class=\"kw-clinique\">végétaux</span> (orties…)</li>\n                <li>Cause fréquente de <span class=\"kw-clinique\">prurit</span> <strong>saisonnier</strong></li>\n                <li>Lésions <span class=\"kw-clinique\">urticariennes</span>, parfois centrées par un point purpurique ou nécrotique</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Cuir chevelu</strong></td>\n            <td>\n              <ol>\n                <li>Rechercher systématiquement une <strong>pédiculose</strong> ++</li>\n                <li>Autres : <span class=\"kw-clinique\">eczéma</span> de contact aux produits capillaires, états pelliculaires, psoriasis / DS, névrodermite (<span class=\"kw-clinique\">lichénification</span> nuque)</li>\n              </ol>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 171 — <span class=\"kw-etio\">Gale</span> et pédiculose · 187 — <span class=\"kw-ci\">Hypersensibilité</span>, allergies cutanées · 117 — <span class=\"kw-clinique\">Psoriasis</span></em></p>","frequence":0},{"id":"116-13","rang":"B","rubrique":"Étiologies","titre":"Connaître les trois causes de prurit spécifiques de la grossesse","contenu":"<p>Trois entités à connaître devant un <span class=\"kw-clinique\">prurit</span> chez la femme enceinte :</p>\n\n      <table >\n        <thead><tr><th>Cause</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Pemphigoïde de la <span class=\"kw-ci\">grossesse</span></strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-def\">DBAI spécifique de la grossesse</span> (auto-Ac anti-BPAG2)</li>\n                <li>2ᵉ-3ᵉ trimestre, plaques urticariennes péri-ombilicales puis bulles</li>\n                <li>Risque de récidive aux grossesses ultérieures, sous CO ou en post-partum</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Éruption</span> polymorphe de la <span class=\"kw-ci\">grossesse</span></strong></td>\n            <td>\n              <ul>\n                <li>Dermatose <span class=\"kw-clinique\">bénigne</span>, 3ᵉ trimestre, primigeste +++</li>\n                <li>Papules urticariennes prurigineuses au sein des <span class=\"kw-clinique\">vergetures</span> abdominales puis <span class=\"kw-imagerie\">diffusion</span></li>\n                <li>Pas de risque fœtal, pas de récidive</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Cholestase intra-hépatique gravidique</strong> 🔥</td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Prurit</span> <span class=\"kw-alerte\">généralisé</span>, sévère, <strong>nu</strong> (sans <span class=\"kw-clinique\">lésion</span> cutanée, hors lésions de grattage)</li>\n                <li>Confirmation par <span class=\"kw-bio\">élévation des sels biliaires sanguins</span> ± cytolyse hépatique modérée</li>\n                <li><span class=\"kw-alerte\">Risque fœtal</span> : prématurité, souffrance fœtale, MFIU → <span class=\"kw-def\">surveillance</span> obstétricale rapprochée + traitement par <span class=\"kw-ttt\">acide ursodésoxycholique</span></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span class=\"kw-ci\">Grossesse</span> normale · 112 — Dermatose bulleuse <span class=\"kw-etio\">auto-immune</span></em></p>","frequence":1},{"id":"116-14","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge du prurit","contenu":"<table >\n        <thead><tr><th>Volet</th><th>Mesures</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Mesures générales</strong></td>\n            <td>\n              <ul>\n                <li><strong>Traitement étiologique +++</strong> (objectif prioritaire)</li>\n                <li><span class=\"kw-ttt\">Arrêt des médicaments</span> suspects d’induire un <span class=\"kw-clinique\">prurit</span> (imputabilité chronologique)</li>\n                <li>Limiter les <strong>facteurs irritants</strong> : antiseptiques, savons parfumés, vêtements serrés et rêches</li>\n                <li><strong>Couper les ongles courts</strong> pour limiter les lésions de grattage</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Traitement symptomatique de la <span class=\"kw-clinique\">xérose</span></strong></td>\n            <td>\n              <ul>\n                <li>Favoriser <span class=\"kw-ttt\">savons surgras</span> et <span class=\"kw-ttt\">syndets</span> pour la toilette</li>\n                <li><span class=\"kw-ttt\">Émollients</span> quotidiens (cérat de Galien, cold-cream) sur tout le tégument après la toilette</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Lésions inflammatoires</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-ttt\">Dermocorticoïdes</span> sur les lésions provoquées par le grattage</li>\n                <li><span class=\"kw-ci\">Non recommandés</span> si <span class=\"kw-clinique\">prurit</span> isolé sans <span class=\"kw-clinique\">lésion</span> <span class=\"kw-etio\">inflammatoire</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Photothérapie</span></strong></td>\n            <td><span class=\"kw-ttt\">UVB</span>, après avis dermatologique spécialisé.</td>\n          </tr>\n          <tr>\n            <td><strong>Anti-histaminiques</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-chiffre\">Ne sont pas un traitement du prurit isolé</span> — efficaces seulement si <span class=\"kw-clinique\">prurit</span> médié par l’histamine (<span class=\"kw-clinique\">urticaire</span> ++)</li>\n                <li>Prescrits le <strong>soir au coucher</strong> en cas de <span class=\"kw-clinique\">prurit</span> <span class=\"kw-alerte\">insomniant</span> : <span class=\"kw-ttt\">anti-H1 de 1ʳᵉ génération</span> (hydroxyzine, doxépine) pour leur effet sédatif</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 187 — <span class=\"kw-ci\">Hypersensibilité</span>, allergies cutanées · 326 — Cadre réglementaire de la prescription et reco pour bon usage</em></p>","frequence":0}],"astuces":[],"strategie":{"hospit":"<p><strong>Avis dermatologique :</strong> requis avant toute <span class=\"kw-ttt\">photothérapie UVB</span>.<br><strong>Orientation étiologique :</strong> prise en charge de la cause selon les résultats du <span class=\"kw-bio\">bilan de 1ʳᵉ intention</span> (<span class=\"kw-ttt\">traitement étiologique</span> prioritaire).</p>","redflags":"<ul><li><span class=\"kw-alerte\">Altération de l'état général</span> associée au <span class=\"kw-clinique\">prurit</span></li><li><span class=\"kw-clinique\">Prurit</span> sévère <span class=\"kw-alerte\">insomniant</span>, retentissant sur le sommeil et les activités quotidiennes</li><li><span class=\"kw-alerte\">Troubles du comportement</span> induits par le <span class=\"kw-clinique\">prurit</span></li><li><span class=\"kw-etio\">Organomégalie</span> à l'examen clinique</li><li><span class=\"kw-clinique\">Prurit</span> diffus <span class=\"kw-clinique\">sine materia</span> imposant un <span class=\"kw-bio\">bilan de cause générale</span></li><li>Lésions de <span class=\"kw-etio\">surinfection</span> : <span class=\"kw-etio\">impétigo</span>, <span class=\"kw-etio\">pyodermite</span></li><li>Retentissement psychique sévère, risque de <span class=\"kw-alerte\">dépression</span> (<span class=\"kw-clinique\">prurit</span> sénile)</li></ul>","principes":"<p><strong>Double objectif :</strong> <span class=\"kw-ttt\">traitement étiologique</span> de la cause + <span class=\"kw-ttt\">traitement symptomatique</span> du <span class=\"kw-clinique\">prurit</span> et de la <span class=\"kw-clinique\">xérose</span>.</p><p><strong>Mesures générales</strong></p><p>general</p><ul><li><strong>Traitement étiologique +++</strong> (objectif prioritaire)</li><li><span class=\"kw-ttt\">Arrêt des médicaments</span> suspects d'induire un <span class=\"kw-clinique\">prurit</span></li><li>Limiter les <span class=\"kw-clinique\">facteurs irritants</span> : antiseptiques, savons parfumés, vêtements serrés et rêches</li><li><span class=\"kw-ttt\">Couper les ongles courts</span> pour limiter les lésions de grattage</li></ul><p><strong>Traitement de la <span class=\"kw-clinique\">xérose</span></strong></p><p>symptomatique</p><ul><li><span class=\"kw-ttt\">Savons surgras</span> / <span class=\"kw-ttt\">syndets</span> pour la toilette</li><li><span class=\"kw-ttt\">Émollients</span> quotidiens (cérat de Galien, cold-cream) sur tout le tégument après la toilette</li></ul><p><strong>Lésions inflammatoires</strong></p><p>symptomatique</p><ul><li><span class=\"kw-ttt\">Dermocorticoïdes</span> sur les lésions provoquées par le grattage</li><li><span class=\"kw-ci\">Non recommandés</span> si <span class=\"kw-clinique\">prurit isolé</span> sans <span class=\"kw-clinique\">lésion</span> <span class=\"kw-etio\">inflammatoire</span></li></ul><p><strong><span class=\"kw-ttt\">Photothérapie</span></strong></p><p>symptomatique</p><ul><li><span class=\"kw-ttt\">Photothérapie UVB</span>, <span class=\"kw-chiffre\">après avis dermatologique</span></li></ul><p><strong>Anti-histaminiques</strong></p><p>symptomatique</p><ul><li><span class=\"kw-chiffre\">Ne sont pas un traitement du prurit isolé</span></li><li>Antiprurigineux uniquement si <span class=\"kw-clinique\">prurit</span> <span class=\"kw-etio\">histamino-médié</span> (<span class=\"kw-clinique\">urticaire</span>)</li><li><span class=\"kw-ttt\">Anti-H1 de 1ʳᵉ génération</span> (<span class=\"kw-ttt\">hydroxyzine</span>, <span class=\"kw-ttt\">doxépine</span>) le soir si <span class=\"kw-clinique\">prurit</span> <span class=\"kw-alerte\">insomniant</span> (effet sédatif)</li></ul>"},"arbre":{"rootId":"start","nodes":[{"id":"start","kind":"root","label":"<span class=\"kw-clinique\">Prurit</span> pathologique confirmé — Lésions de grattage et/ou retentissement (sommeil, activités). 1ʳᵉ étape : prurit <span class=\"kw-clinique\">localisé</span> ou <span class=\"kw-clinique\">diffus</span> ?","detail":"<h4><span class=\"kw-clinique\">Prurit</span> — démarche diagnostique et conduite à tenir — Caractériser (localisé / diffus, avec / sans lésion) → bilan ciblé → traitement étiologique + symptomatique</h4>","branches":[{"to":"q-diffus","label":"Prurit diffus","color":"blue"},{"to":"q-local","label":"Prurit localisé","color":"blue"}]},{"id":"q-diffus","kind":"decision","label":"<span class=\"kw-clinique\">Prurit</span> diffus — Examen cutané complet : existe-t-il des <span class=\"kw-clinique\">lésions cutanées spécifiques</span> (hors lésions de grattage) ?","branches":[{"to":"t-dermatose","label":"Avec lésions spécifiques","color":"green"},{"to":"q-bilan","label":"Sans lésion (sine materia)","color":"blue"}]},{"id":"t-dermatose","kind":"terminal","label":"Dermatose spécifique en cause — Les lésions spécifiques orientent le diagnostic","color":"green","detail":"<h4>Conduite</h4><ul><li>Identifier et traiter la <span class=\"kw-etio\">dermatose</span> causale (ex. <span class=\"kw-etio\">lichen plan</span>, <span class=\"kw-etio\">mastocytose cutanée</span> selon la clinique)</li><li>+ <span class=\"kw-ttt\">traitement symptomatique</span> commun (<span class=\"kw-ttt\">émollients</span>, anti-grattage)</li></ul>"},{"id":"q-bilan","kind":"decision","label":"Sine materia → bilan de 1ʳᵉ intention — Bilan systématique à la recherche d'une <span class=\"kw-etio\">cause générale</span>","branches":[{"to":"t-etiologique","label":"Cause générale identifiée","color":"green"},{"to":"t-symptomatique","label":"Bilan négatif / pas de cause curable","color":"amber"}]},{"id":"t-etiologique","kind":"terminal","label":"Traitement étiologique","color":"green","detail":"<h4>Priorité</h4><ul><li><span class=\"kw-ttt\">Traitement de la cause</span> générale identifiée +++</li><li>+ <span class=\"kw-ttt\">traitement symptomatique</span> associé</li></ul>"},{"id":"t-symptomatique","kind":"terminal","label":"Traitement symptomatique","color":"green","detail":"<h4>Mesures générales</h4><ul><li><span class=\"kw-ttt\">Arrêt des médicaments</span> suspects</li><li>Limiter les <span class=\"kw-clinique\">facteurs irritants</span> (antiseptiques, savons parfumés, vêtements serrés / rêches)</li><li><span class=\"kw-ttt\">Couper les ongles courts</span></li></ul><h4><span class=\"kw-clinique\">Xérose</span> & symptômes</h4><ul><li><span class=\"kw-ttt\">Savons surgras</span> / <span class=\"kw-ttt\">syndets</span> + <span class=\"kw-ttt\">émollients</span> quotidiens (cérat de Galien, cold-cream)</li><li><span class=\"kw-ttt\">Dermocorticoïdes</span> sur les lésions inflammatoires de grattage (<span class=\"kw-ci\">pas si prurit isolé</span>)</li><li><span class=\"kw-ttt\">Anti-H1 sédatifs</span> le soir si <span class=\"kw-clinique\">prurit</span> <span class=\"kw-alerte\">insomniant</span> (hydroxyzine, doxépine)</li><li><span class=\"kw-ttt\">Photothérapie UVB</span> <span class=\"kw-chiffre\">après avis dermatologique</span></li></ul>"},{"id":"q-local","kind":"decision","label":"<span class=\"kw-clinique\">Prurit</span> localisé — Préciser la <span class=\"kw-clinique\">topographie</span> et le contexte","branches":[{"to":"t-scalp","label":"Cuir chevelu","color":"green"},{"to":"t-local","label":"Autre topographie","color":"green"}]},{"id":"t-scalp","kind":"terminal","label":"Cuir chevelu → pédiculose ++","color":"green","detail":"<h4>À rechercher en premier</h4><ul><li><span class=\"kw-etio\">Pédiculose</span> du cuir chevelu, systématiquement</li><li>Autres : <span class=\"kw-etio\">eczéma de contact</span> aux cosmétiques capillaires, <span class=\"kw-etio\">états pelliculaires</span>, <span class=\"kw-etio\">psoriasis</span> / <span class=\"kw-etio\">dermatite séborrhéique</span>, <span class=\"kw-etio\">névrodermite</span> (<span class=\"kw-clinique\">lichénification</span> de la nuque)</li></ul>"},{"id":"t-local","kind":"terminal","label":"Dermatose / parasitose localisée","color":"green","detail":"<h4>Étiologies à évoquer</h4><ul><li><span class=\"kw-etio\">Mycoses</span> (candidose, dermatophytose)</li><li><span class=\"kw-etio\">Ectoparasitoses</span> : <span class=\"kw-etio\">gale</span> (recrudescence <span class=\"kw-clinique\">nocturne</span>, familial), <span class=\"kw-etio\">pédiculose</span></li><li><span class=\"kw-etio\">Helminthiases tropicales</span> si <span class=\"kw-clinique\">séjour tropical</span> → <span class=\"kw-bio\">hyperéosinophilie</span>, <span class=\"kw-etio\">larva migrans</span></li><li><span class=\"kw-etio\">Parasitoses autochtones</span> (<span class=\"kw-etio\">dermatite des nageurs</span>)</li><li><span class=\"kw-etio\">Piqûres</span> (insectes, végétaux)</li></ul>"}]},"cards":[{"i":"0b25ec2c5a1d","n":116,"o":"116-1","u":"Définition","t":"Connaître la définition du prurit, du prurit sine materia et du prurit aquagénique","q":"Qu'est-ce que le prurit <i>sine materia</i> et quelle est sa signification clinique ?","a":"<p>Le prurit <i>sine materia</i> est un prurit objectivé <strong>sans lésion cutanée spécifique</strong> (en dehors des lésions secondaires de grattage). Sa présence oriente vers une <strong>cause générale sous-jacente</strong>, telle qu'une maladie hématologique, hépatique, rénale, endocrinienne ou une origine médicamenteuse.</p>"},{"i":"5c50163e3343","n":116,"o":"116-1","u":"Définition","t":"Connaître la définition du prurit, du prurit sine materia et du prurit aquagénique","q":"À quel moment considère-t-on qu'un prurit devient pathologique ?","a":"<p>Un prurit est considéré comme pathologique lorsqu'il induit :</p><ul><li>Des <strong>lésions de grattage</strong>.</li><li>Un <strong>retentissement sur les activités quotidiennes</strong> ou le <strong>sommeil</strong>.</li></ul>"},{"i":"68be111ca5cf","n":116,"o":"116-1","u":"Définition","t":"Connaître la définition du prurit, du prurit sine materia et du prurit aquagénique","q":"Quelle est la définition du prurit en médecine ?","a":"<p>Le prurit est un <strong>signe fonctionnel</strong>, une <strong>sensation cutanée désagréable</strong> qui provoque le besoin irrépressible de se gratter. Il peut être localisé ou généralisé et ne concerne que la peau et certaines (semi-)muqueuses.</p>"},{"i":"b42a54d9278b","n":116,"o":"116-1","u":"Définition","t":"Connaître la définition du prurit, du prurit sine materia et du prurit aquagénique","q":"Qu'est-ce que le prurit aquagénique et quelle étiologie doit-on systématiquement rechercher en sa présence ?","a":"<p>Le prurit aquagénique est un prurit déclenché par le <strong>contact de l'eau</strong>, quelle que soit sa température, et cela <strong>sans lésion cutanée</strong> associée. Il faut systématiquement rechercher une <strong>maladie de Vaquez</strong> (polyglobulie primitive).</p>"},{"i":"2836463a8f47","n":116,"o":"116-11","u":"Étiologies","t":"Connaître une cause de prurit du scalp à rechercher systématiquement","q":"Quelle cause de prurit du cuir chevelu doit être systématiquement recherchée, quel que soit l'âge ou le milieu social ?","a":"<p>Il faut systématiquement rechercher une <strong>pédiculose du cuir chevelu</strong>, due à <em>Pediculus humanus capitis</em>.</p>"},{"i":"3761cc96d88f","n":116,"o":"116-11","u":"Étiologies","t":"Connaître une cause de prurit du scalp à rechercher systématiquement","q":"Quels sont les éléments clés à rechercher lors de l'examen clinique d'une suspicion de pédiculose du cuir chevelu ?","a":"<p>L'examen clinique doit être soigneux et rechercher :</p><ul><li>Les <strong>lentes accrochées à la racine des cheveux</strong>.</li><li>Les localisations préférentielles : <strong>derrière les oreilles et dans la nuque</strong>.</li></ul>"},{"i":"e0d7c23ae650","n":116,"o":"116-11","u":"Étiologies","t":"Connaître une cause de prurit du scalp à rechercher systématiquement","q":"Quelles sont les autres causes fréquentes de prurit du cuir chevelu, en dehors de la pédiculose ?","a":"<p>Les autres causes communes de prurit du cuir chevelu incluent :</p><ul><li>L'<strong>intolérance ou l'eczéma de contact</strong> aux produits cosmétiques capillaires (teintures, shampooings, défrisants).</li><li>Les <strong>états pelliculaires simples</strong>.</li><li>Les dermatoses inflammatoires comme le <strong>psoriasis</strong> ou la <strong>dermatite séborrhéique</strong>.</li><li>La <strong>névrodermite de la nuque</strong>, souvent associée à une lichénification due au grattage chronique.</li></ul>"},{"i":"0886383c8415","n":116,"o":"116-14","u":"Prise en charge","t":"Connaître les principes de la prise en charge du prurit","q":"Quelles sont les mesures générales à mettre en œuvre pour prendre en charge un prurit ?","a":"<ul><li><strong>Arrêt des médicaments suspects</strong> d'induire un prurit, en évaluant l'imputabilité chronologique.</li><li>Limiter les facteurs irritants : <strong>antiseptiques</strong>, <strong>savons parfumés</strong>, vêtements serrés et rêches.</li><li><strong>Couper les ongles courts</strong> pour limiter les lésions de grattage.</li></ul>"},{"i":"6e6af9e663c2","n":116,"o":"116-14","u":"Prise en charge","t":"Connaître les principes de la prise en charge du prurit","q":"Quand les dermocorticoïdes sont-ils indiqués dans la prise en charge du prurit ?","a":"<p>Les dermocorticoïdes sont indiqués sur les <strong>lésions inflammatoires provoquées par le grattage</strong>. Ils ne sont <strong>pas recommandés en cas de prurit isolé sans lésion inflammatoire</strong>.</p>"},{"i":"a06eb91741d6","n":116,"o":"116-14","u":"Prise en charge","t":"Connaître les principes de la prise en charge du prurit","q":"Quelle est l'indication des anti-histaminiques dans la prise en charge du prurit ?","a":"<p>Les anti-histaminiques ne sont <strong>pas un traitement du prurit isolé</strong>. Ils sont efficaces si le prurit est médié par l'histamine (notamment dans l'<strong>urticaire</strong>). En cas de prurit insomniant, des <strong>anti-H1 de 1<sup>re</sup> génération</strong> (comme l'<strong>hydroxyzine</strong> ou la <strong>doxépine</strong>) peuvent être prescrits le soir au coucher pour leur effet sédatif.</p>"},{"i":"a29788101960","n":116,"o":"116-14","u":"Prise en charge","t":"Connaître les principes de la prise en charge du prurit","q":"Quel est l'objectif prioritaire de la prise en charge du prurit ?","a":"<p>L'objectif prioritaire dans la prise en charge du prurit est le <strong>traitement étiologique</strong> de la cause sous-jacente.</p>"},{"i":"c492dff79681","n":116,"o":"116-14","u":"Prise en charge","t":"Connaître les principes de la prise en charge du prurit","q":"Comment prend-on en charge la xérose cutanée dans le cadre d'un prurit ?","a":"<p>Le traitement symptomatique de la xérose repose sur :</p><ul><li>La favorisation de <strong>savons surgras</strong> et <strong>syndets</strong> pour la toilette.</li><li>L'application quotidienne d'<strong>émollients</strong> (ex: <strong>cérat de Galien</strong>, <strong>cold-cream</strong>) sur tout le tégument après la toilette.</li></ul>"},{"i":"1391a348ca2a","n":116,"o":"116-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un prurit","q":"Quelles sont les autres sensations cutanées à distinguer du prurit ?","a":"<p>Il est essentiel de distinguer le prurit d'autres sensations cutanées telles que les <strong>dysesthésies</strong>, les <strong>paresthésies</strong> et la <strong>douleur</strong>.</p>"},{"i":"37959a131504","n":116,"o":"116-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un prurit","q":"Quels éléments de la démarche clinique orientent l'étiologie d'un prurit ?","a":"<p>La démarche clinique pour l'orientation étiologique d'un prurit inclut :</p><ul><li>Le caractère <strong>localisé ou diffus</strong> du prurit.</li><li>L'évaluation de sa <strong>sévérité</strong> (insomnie, troubles du comportement, AEG).</li><li>Les <strong>circonstances déclenchantes, aggravantes, apaisantes</strong> et les <strong>horaires de survenue</strong>.</li><li>Le <strong>métier</strong> du patient, la prise de <strong>médicaments</strong>, et le caractère <strong>collectif</strong> (entourage).</li><li>La recherche d'<strong>autres lésions cutanées</strong>, d'un <strong>dermographisme</strong> ou d'une <strong>organomégalie</strong>.</li></ul>"},{"i":"3992259a6d3a","n":116,"o":"116-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un prurit","q":"Quelles lésions élémentaires non spécifiques doit-on rechercher lors de l'examen cutané face à un prurit ?","a":"<p>Face à un prurit, il faut rechercher des <strong>lésions de grattage</strong> qui sont non spécifiques, telles que :</p><ul><li>Des <strong>excoriations</strong></li><li>Des <strong>stries linéaires</strong></li><li>Des <strong>ulcérations</strong></li></ul>"},{"i":"99abdd36fd5a","n":116,"o":"116-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un prurit","q":"Comment établit-on le diagnostic positif d'un prurit ?","a":"<p>Le diagnostic positif d'un prurit est essentiellement <strong>clinique</strong>, reposant sur l'<strong>interrogatoire</strong> approfondi du patient et un <strong>examen cutanéo-muqueux complet</strong>.</p>"},{"i":"d7a40487ff82","n":116,"o":"116-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un prurit","q":"Quelles surinfections cutanées peuvent être associées à un prurit chronique ?","a":"<p>Un prurit chronique peut entraîner des surinfections cutanées telles que l'<strong>impétigo</strong> et les <strong>pyodermites</strong>.</p>"},{"i":"f7c48f619c51","n":116,"o":"116-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un prurit","q":"Quelles sont les lésions élémentaires à rechercher évoquant la chronicité d'un prurit ?","a":"<p>La chronicité d'un prurit peut être évoquée par la présence de :</p><ul><li><strong>Prurigo</strong> : lésions papulo-vésiculeuses, papules excoriées, papules croûteuses, nodules.</li><li><strong>Lichénification</strong> : peau épaissie, grisâtre, recouverte de fines squames dessinant un quadrillage.</li></ul>"},{"i":"39f5cd43d055","n":116,"o":"116-6","u":"Examens complémentaires","t":"Connaître les examens à réaliser en première intention dans le cadre d’un prurit sine materia","q":"Quel examen d'imagerie est indiqué en première intention dans le bilan d'un prurit sine materia ?","a":"<p>L'examen d'imagerie indiqué en première intention dans le bilan d'un prurit sine materia est une <strong>radiographie thoracique (RXT)</strong> pour rechercher un lymphome.</p>"},{"i":"e88fbadf7ed2","n":116,"o":"116-6","u":"Examens complémentaires","t":"Connaître les examens à réaliser en première intention dans le cadre d’un prurit sine materia","q":"Quels bilans biologiques de première intention doivent être réalisés devant un prurit sine materia ?","a":"<p>Devant un prurit sine materia, les bilans biologiques de première intention à réaliser sont :</p><ul><li><strong>NFS-Plaquettes</strong> et <strong>Ferritine</strong> pour rechercher une anémie ferriprive ou une hémopathie.</li><li><strong>γ-GT</strong> et <strong>PAL</strong> pour évaluer une cholestase.</li><li><strong>Créatinine</strong> pour dépister une insuffisance rénale.</li><li><strong>TSH</strong> pour explorer une dysthyroïdie.</li><li><strong>Électrophorèse des protéines plasmatiques</strong> pour rechercher une LLC ou une gammapathie.</li></ul>"},{"i":"ec70c07c556f","n":116,"o":"116-6","u":"Examens complémentaires","t":"Connaître les examens à réaliser en première intention dans le cadre d’un prurit sine materia","q":"Quelles sérologies infectieuses sont à demander en première intention devant un prurit sine materia ?","a":"<p>Devant un prurit sine materia, les sérologies infectieuses à demander en première intention sont :</p><ul><li><strong>VIH</strong></li><li><strong>VHB</strong></li><li><strong>VHC</strong></li></ul>"},{"i":"ff673adce074","n":116,"o":"116-6","u":"Examens complémentaires","t":"Connaître les examens à réaliser en première intention dans le cadre d’un prurit sine materia","q":"Quels examens ne sont PAS indiqués en première intention devant un prurit sine materia ?","a":"<p>Les examens qui ne sont <strong>pas indiqués en première intention</strong> devant un prurit sine materia sont :</p><ul><li>L'<strong>échographie abdominale</strong> (recherche de cause hépatique).</li><li>La <strong>biopsie cutanée</strong>.</li></ul>"},{"i":"1813a5c0f230","n":116,"o":"116-7","u":"Étiologies","t":"Connaître l’arbre décisionnel pour le diagnostic étiologique du prurit","q":"Quelles sont les principales causes de prurit diffus sans lésions cutanées spécifiques (sine materia) ?","a":"<p>Les principales causes de prurit diffus sans lésions cutanées spécifiques (sine materia) incluent :</p><ul><li>La <strong>cholestase</strong> (VBP, médicamenteuse, grossesse).</li><li>L'<strong>insuffisance rénale chronique</strong>.</li><li>Certaines <strong>hémopathies</strong> : maladie de Vaquez, LLC, lymphome d'Hodgkin ou non hodgkinien.</li><li>Les <strong>endocrinopathies</strong>, notamment la dysthyroïdie.</li><li>Les causes <strong>médicamenteuses</strong>.</li><li>L'infection par le <strong>VIH</strong>.</li><li>Le <strong>prurit sénile</strong> (souvent lié à une xérose).</li><li>Le <strong>prurit psychogène</strong> (par élimination).</li></ul>"},{"i":"1e00435cb6b0","n":116,"o":"116-7","u":"Étiologies","t":"Connaître l’arbre décisionnel pour le diagnostic étiologique du prurit","q":"Quels éléments rechercher systématiquement lors de l'interrogatoire et de l'examen clinique d'un patient présentant un prurit ?","a":"<p>Il faut systématiquement rechercher :</p><ul><li>Un caractère <strong>familial ou collectif</strong>.</li><li>Un <strong>horaire nocturne</strong>.</li><li>Des <strong>circonstances déclenchantes</strong> spécifiques (eau, effort, contact).</li><li>La prise de <strong>médicaments récents</strong>.</li><li>Un <strong>voyage tropical</strong> récent.</li><li>Une <strong>organomégalie</strong> à l'examen clinique.</li></ul>"},{"i":"1e735dcca903","n":116,"o":"116-7","u":"Étiologies","t":"Connaître l’arbre décisionnel pour le diagnostic étiologique du prurit","q":"Quelle est l'approche diagnostique initiale face à un prurit pour orienter les étiologies ?","a":"<p>L'orientation étiologique d'un prurit repose sur deux axes successifs :</p><ul><li>Prurit <strong>localisé</strong> ou <strong>diffus</strong>.</li><li>Présence ou absence de <strong>lésions cutanées spécifiques</strong>.</li></ul>"},{"i":"8377e91b670e","n":116,"o":"116-7","u":"Étiologies","t":"Connaître l’arbre décisionnel pour le diagnostic étiologique du prurit","q":"Quelles sont les étiologies courantes d'un prurit localisé ?","a":"<p>Les étiologies courantes d'un prurit localisé sont :</p><ul><li>Les <strong>dermatoses débutantes</strong> (eczéma, psoriasis, lichen).</li><li>Les <strong>mycoses</strong> (candidose, dermatophytose).</li><li>Les <strong>ectoparasitoses</strong> (gale, pédiculose notamment du cuir chevelu).</li><li>Les <strong>helminthiases tropicales</strong> (ex: larva migrans).</li><li>La <strong>dermatite des nageurs</strong> (parasitoses autochtones).</li><li>Les <strong>piqûres</strong> (insectes, végétaux).</li><li>Les prurits <strong>anal, vulvaire, scrotal</strong> isolés.</li></ul>"},{"i":"91dbf62d7dda","n":116,"o":"116-7","u":"Étiologies","t":"Connaître l’arbre décisionnel pour le diagnostic étiologique du prurit","q":"Quelles sont les principales étiologies à évoquer face à un prurit diffus avec lésions cutanées spécifiques ?","a":"<p>Devant un prurit diffus avec lésions cutanées spécifiques, les principales étiologies sont :</p><ul><li>La <strong>gale</strong> (recrudescence nocturne, caractère familial, sillons interdigitaux).</li><li>L'<strong>urticaire</strong> ou le dermographisme.</li><li>L'<strong>eczéma</strong> (atopique, de contact).</li><li>Les <strong>toxidermies</strong> médicamenteuses.</li><li>Le <strong>psoriasis</strong>, la mastocytose, le lichen plan.</li></ul>"},{"i":"7122ba1ab610","n":116,"o":"116-8","u":"Étiologies","t":"Connaître trois causes principales de prurit diffus avec lésions cutanées","q":"Lorsque l'on a un patient présentant un prurit diffus avec des lésions cutanées fugaces (< 24h), érythémateuses et œdémateuses, quelle est la dermatose à évoquer en première intention ?","a":"<p>Il faut évoquer l'<strong>urticaire</strong>. Ces lésions sont des papules œdémateuses érythémateuses et prurigineuses, fugaces, avec un mécanisme histaminique expliquant une bonne réponse aux anti-H1. Un dermographisme est parfois présent.</p>"},{"i":"a681f3229fa1","n":116,"o":"116-8","u":"Étiologies","t":"Connaître trois causes principales de prurit diffus avec lésions cutanées","q":"Quelle affection dermatologique courante se manifeste par un prurit diffus et une sémiologie cutanée caractérisée par des sillons, des vésicules perlées, et une topographie évocatrice des espaces interdigitaux et des poignets ?","a":"<p>Il s'agit de la <strong>gale</strong>. Le prurit est généralisé, à recrudescence nocturne, souvent familial ou collectif, et peut affecter les OGE, les mamelons et l'ombilic.</p>"},{"i":"f83129bfe54d","n":116,"o":"116-8","u":"Étiologies","t":"Connaître trois causes principales de prurit diffus avec lésions cutanées","q":"Comment différencier cliniquement un eczéma d'autres dermatoses prurigineuses diffuses avec lésions cutanées, en se basant sur le type de lésions cutanées et leur évolution ?","a":"<p>L'<strong>eczéma</strong> se caractérise par des lésions <strong>érythémato-vésiculeuses</strong>, souvent <strong>suintantes</strong> puis <strong>croûteuses</strong>, et mal limitées. Il peut être atopique (touchant les plis) ou de contact (topographie de contact). En cas de chronicité, il évolue vers la <strong>lichénification</strong>.</p>"},{"i":"0f860ed91120","n":116,"o":"116-9","u":"Étiologies","t":"Connaître les différentes causes de prurit diffus sine materia","q":"Quelles sont les causes endocriniennes, infectieuses et médicamenteuses de prurit diffus sine materia ?","a":"<p>Les causes endocriniennes, infectieuses et médicamenteuses de prurit diffus sine materia comprennent :</p><ul><li><strong>Endocriniennes</strong> : Dysthyroïdie, principalement l'<strong>hyperthyroïdie</strong>.</li><li><strong>Infectieuses</strong> : <strong>VIH</strong>, où le prurit est fréquent, parfois associé à une éruption papuleuse.</li><li><strong>Médicamenteuses</strong> : Il s'agit de <strong>toxidermies non éruptives</strong>, impliquant divers médicaments comme les <strong>opiacés</strong>, les <strong>IEC</strong>, les <strong>β-bloquants</strong>, les <strong>AINS</strong>, les <strong>antibiotiques</strong>, ou les <strong>antipaludéens</strong>. L'imputabilité est chronologique.</li></ul>"},{"i":"759e07404534","n":116,"o":"116-9","u":"Étiologies","t":"Connaître les différentes causes de prurit diffus sine materia","q":"Quelles sont les causes rénales et hématologiques de prurit diffus sine materia ?","a":"<p>Les causes rénales et hématologiques de prurit diffus sine materia sont :</p><ul><li><strong>Rénale</strong> : <strong>insuffisance rénale chronique évoluée</strong>, notamment chez les patients dialysés.</li><li><strong>Hématologiques</strong> :<ul><li><strong>Maladie de Vaquez</strong> (polyglobulie primitive) : le <strong>prurit aquagénique</strong> est très évocateur.</li><li><strong>Leucémie lymphoïde chronique (LLC)</strong>.</li><li><strong>Lymphomes</strong> (Hodgkin ou Non Hodgkinien), où le prurit peut être inaugural.</li><li><strong>Anémie ferriprive</strong>.</li></ul></li></ul>"},{"i":"b87f4e3a09f4","n":116,"o":"116-9","u":"Étiologies","t":"Connaître les différentes causes de prurit diffus sine materia","q":"Quelles sont les causes hépatiques pouvant provoquer un prurit diffus sine materia ?","a":"<p>Les causes hépatiques de prurit diffus sine materia sont liées à la <strong>cholestase</strong>. Elle peut être due à :</p><ul><li>Une atteinte des <strong>voies biliaires (VBP) intra ou extra-hépatiques</strong>.</li><li>Une <strong>cirrhose biliaire primitive</strong> (CBP).</li><li>Une cholestase <strong>médicamenteuse</strong> ou <strong>gravidique</strong>.</li></ul>"},{"i":"d7b964b6c6a8","n":116,"o":"116-9","u":"Étiologies","t":"Connaître les différentes causes de prurit diffus sine materia","q":"Quelles sont les caractéristiques du prurit sénile et du prurit psychogène ?","a":"<p>Les caractéristiques du prurit sénile et du prurit psychogène sont :</p><ul><li><strong>Prurit sénile</strong> : Fréquent chez le sujet âgé, lié au <strong>vieillissement cutané</strong> et des terminaisons nerveuses. Il est favorisé par la <strong>xérose cutanée</strong>, et peut être <strong>insomniant</strong> malgré la discrétion des lésions. Un <strong>retentissement psychique</strong> (dépression) est possible.</li><li><strong>Prurit psychogène</strong> : C'est un <strong>diagnostic d'élimination</strong> (à ne pas confondre avec le prurit idiopathique). Il est important de rechercher une <strong>pathologie psychiatrique associée</strong> ou des <strong>événements stressants déclenchants</strong>.</li></ul>"}]};